-- (proposal $S/agJE-4608/: verify_extraction / verify_order repaired-reference fallback).
--
-- Page-scoped source_content_confirmed assertions with detail.purpose = 'repaired-reference-difference'. Each lists
-- the EXACT strings by which page N of Poppler's text of the MuPDF xref-rebuilt copy differs from the stored page
-- (missing_strings: in the reference, not stored; extra_strings: stored, not in the reference), bound to the reference
-- page text by reference_page_sha256. The staged verifier credits a string only if it is printed in that page; a
-- changed reference page credits nothing.
--
-- Apply ONLY after the verifier proposal is merged; then re-run
--   python -m nizam.workers.verify_extraction --document-id 4608
--   python -m nizam.workers.verify_order --document-id 4608
-- Measured with the staged code (dry run, no writes): recall 0.97878 raw -> 1.0 credited, precision 0.99362 raw
-- -> 1.0 credited, ordered-character precision 0.9819 (passed).

BEGIN;

